package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator.writeBoolean.
 * Focuses on maximizing branch and line coverage, specifically testing
 * the buffer flushing logic and the boolean state mapping.
 */
public class UTF8JsonGenerator_writeBoolean_TriageGen2Test {

    private ByteArrayOutputStream out;
    private IOContext iocontext;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        iocontext = IOContext.bootstrap(null);
        codec = null; // Not strictly needed for writeBoolean
    }

    @Test
    public void testWriteBooleanTrue() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(iocontext, 0, codec, out);
        gen.writeBoolean(true);
        gen.flush();

        // "true" in UTF-8 is [116, 114, 117, 101]
        byte[] expected = "true".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanFalse() throws IOException {
        UTF8JsonGenerator gen = new UTF8JsonGenerator(iocontext, 0, codec, out);
        gen.writeBoolean(false);
        gen.flush();

        // "false" in UTF-8 is [102, 97, 108, 115, 101]
        byte[] expected = "false".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanTriggersFlush() throws IOException {
        // To test the branch: if ((_outputTail + 5) >= _outputEnd)
        // We use a small buffer provided via the second constructor.
        // The internal buffer size is determined by the byte array passed.

        byte[] smallBuffer = new byte[10];
        // We want to force _outputTail + 5 >= _outputEnd.
        // If we write something that brings _outputTail to 6, 6 + 5 = 11, which is >= 10.

        // Note: We can't easily manipulate _outputTail directly, 
        // so we fill it up using other methods first if possible, 
        // or use a very small buffer and write a string first.

        UTF8JsonGenerator gen = new UTF8JsonGenerator(iocontext, 0, codec, out, smallBuffer, 0, false);

        // 1. Write a string to advance _outputTail. 
        // "12345" is 5 bytes.
        gen.writeRaw("12345"); 

        // Now _outputTail is 5.
        // When we call writeBoolean(true), len is 4.
        // (5 + 5) >= 10 is TRUE. It should trigger _flushBuffer().

        gen.writeBoolean(true);
        gen.flush();

        byte[] expected = "12345true".getBytes();
        assertArrayEquals(expected, out.toByteArray());
    }

    @Test
    public void testWriteBooleanNoImmediateFlush() throws IOException {
        // Use a larger buffer so that (_outputTail + 5) < _outputEnd
        byte[] largeBuffer = new byte[100];
        UTF8JsonGenerator gen = new UTF8JsonGenerator(iocontext, 0, codec, out, largeBuffer, 0, false);

        gen.writeBoolean(true);

        // Since buffer is large, it shouldn't have flushed to 'out' yet.
        assertEquals(0, out.size());

        gen.flush();
        assertArrayEquals("true".getBytes(), out.toByteArray());
    }

    @Test
    public void testWriteBooleanWithVerySmallBuffer() throws IOException {
        // Test the edge case where the buffer is almost full.
        // Buffer size 5.
        byte[] tinyBuffer = new byte[5];
        UTF8JsonGenerator gen = new UTF8JsonGenerator(iocontext, 0, codec, out, tinyBuffer, 0, false);

        // _outputTail is 0. 0 + 5 >= 5 is TRUE.
        // This should trigger flush immediately before writing.
        gen.writeBoolean(false);
        gen.flush();

        assertArrayEquals("false".getBytes(), out.toByteArray());
    }
}
